"""FROZEN reference: the pre-merge ``pre_proxy_url`` body from git HEAD.

Captured from ``services/protocol-payment/ideal/ideal_qr_extract.py`` at commit
6acafb5, before stage 2 (batch 8) moved the resolver into
``common/extractor_runtime.py``. ideal and twint were byte-identical apart from
the env-var prefix; blik was the same body minus the dead ``raw = ""`` tail
(which could only ever return ``""``), so one copy represents all three.

**Do not edit this file.** It is the "before" side of the differential test in
``tests/governance/test_stage2_replay_selfcheck.py``; editing it turns that test
into a comparison of the new code against itself.

The only transformation applied is dependency injection: ``environ``,
``normalize`` and ``register`` arrive through ``Seams``, and the provider
env-var tuple is passed in (it is data, not logic). No statement, literal or
expression was rewritten -- including the dead tail, kept so the comparison is
against the real HEAD body rather than a cleaned-up paraphrase.
"""

from __future__ import annotations

from collections.abc import Callable, Mapping, Sequence


class Seams:
    """The per-extractor values and callables the pre-merge body closed over."""

    def __init__(
        self,
        *,
        environ: Mapping[str, str],
        normalize: Callable[[str], str],
        register: Callable[[str], None],
    ) -> None:
        self.environ = environ
        self.normalize = normalize
        self.register = register


def pre_proxy_url(env_names: Sequence[str], *, seams: Seams) -> str:
    for name in env_names:
        if name in seams.environ:
            raw = seams.environ.get(name, "").strip()
            if raw.lower() in {"", "0", "off", "none", "direct", "disabled"}:
                return ""
            proxy = seams.normalize(raw)
            seams.register(proxy)
            return proxy
    raw = ""
    return seams.normalize(raw) if raw else ""
